154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    /**
160	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
161	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
162	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
163	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
164	     *
165	     * @param city     the owner's city
166	     * @param lastName the owner's last name
167	     * @return the assigned customer code
168	     */
169	    private String nextCustomerCode(String city, String lastName) {
170	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
171	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
172	        int sequence = (int) this.clinicService.findAllOwners().stream()
173	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
174	            .count() + 1;
175	        return String.format("%s-%s-%04d", city3, last3, sequence);
176	    }
177	
178	    /**
179	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
180	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
181	     *
182	     * @param customerCode     the owner's assigned customer code
183	     * @param registrationDate the owner's registration date
184	     * @return the assigned membership number
185	     */
186	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
187	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
188	    }
189	
190	    /**
191	     * Counts the existing owners that already share the given firstName and lastName, compared
192	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
193	     * the owners that pre-existed this create.
194	     *
195	     * @param firstName the new owner's first name
196	     * @param lastName  the new owner's last name
197	     * @return the number of existing namesakes
198	     */
199	    private int countNamesakes(String firstName, String lastName) {
200	        return (int) this.clinicService.findAllOwners().stream()
201	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
202	                && equalsIgnoreCase(existing.getLastName(), lastName))
203	            .count();
204	    }
205	
206	    /**
207	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
208	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
209	     * customer-code sequence is derived.
210	     *
211	     * @param city the new owner's city
212	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
213	     */
214	    private void rejectWhenCityAtCapacity(String city) {
215	        long count = this.clinicService.findAllOwners().stream()
216	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
217	            .count();
218	        if (count >= CITY_CAPACITY) {
219	            throw new CityAtCapacityException(city);
220	        }
221	    }
222	
223	    private boolean equalsIgnoreCase(String a, String b) {
224	        return a == null ? b == null : a.equalsIgnoreCase(b);
225	    }
226	
227	    /**
228	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
229	     * offending field so the client learns about all of them at once.
230	     *
231	     * @param ownerFieldsDto the submitted owner fields
232	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
233	     *                                     missing or blank
234	     */
235	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
236	        List<String> errors = new ArrayList<>();
237	        if (isBlank(ownerFieldsDto.getFirstName())) {
238	            errors.add("firstName");
239	        }
240	        if (isBlank(ownerFieldsDto.getLastName())) {
241	            errors.add("lastName");
242	        }
243	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
244	            errors.add("address");
245	        }
246	        if (isBlank(ownerFieldsDto.getCity())) {
247	            errors.add("city");
248	        }
249	        if (isBlank(ownerFieldsDto.getTelephone())) {
250	            errors.add("telephone");
251	        }
252	        if (!errors.isEmpty()) {
253	            throw new MissingOwnerFieldsException(errors);
254	        }
255	    }
256	
257	    private boolean isBlank(String value) {
258	        return value == null || value.isBlank();
259	    }
260	
261	    /**
262	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
263	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
264	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
265	     * followed by 8 to 15 digits.
266	     *
267	     * @param telephone the raw telephone value as submitted
268	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
269	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
270	     */
271	    private String normalizeTelephone(String telephone) {
272	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
273	        String nationalSignificantNumber;
274	        if (cleaned.startsWith("+")) {
275	            nationalSignificantNumber = cleaned.substring(1);
276	        } else {
277	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
278	            nationalSignificantNumber = "61" + national;
279	        }
280	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
281	            throw new InvalidTelephoneException(telephone);
282	        }
283	        return "+" + nationalSignificantNumber;
284	    }
285	
286	    /**
287	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
288	     * value is treated as absent and returns {@code null}); when present the value must be a
289	     * syntactically valid address, and is stored and returned lower-cased.
290	     *
291	     * @param email the raw email value as submitted, may be {@code null}
292	     * @return the lower-cased email, or {@code null} when none was supplied
293	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
294	     */
295	    private String normalizeEmail(String email) {
296	        if (email == null || email.isBlank()) {
297	            return null;
298	        }
299	        String normalized = email.trim().toLowerCase();
300	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
301	            throw new InvalidEmailException(email);
302	        }
303	        return normalized;
304	    }
305	
306	    /**
307	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
308	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
309	     * comparison, so numbers that differ only in formatting still count as duplicates.
310	     *
311	     * @param e164Telephone the E.164 telephone of the owner being created
312	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
313	     */
314	    private void rejectDuplicateTelephone(String e164Telephone) {
315	        boolean inUse = this.clinicService.findAllOwners().stream()
316	            .map(Owner::getTelephone)
317	            .filter(existing -> existing != null)
318	            .map(this::toComparableTelephone)
319	            .filter(existing -> existing != null)
320	            .anyMatch(e164Telephone::equals);
321	        if (inUse) {
322	            throw new DuplicateTelephoneException(e164Telephone);
323	        }
324	    }
325	
326	    /**
327	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
328	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
329	     * than aborting the whole create.
330	     */
331	    private String toComparableTelephone(String telephone) {
332	        try {
333	            return normalizeTelephone(telephone);
334	        } catch (InvalidTelephoneException ex) {
335	            return null;
336	        }
337	    }
338	
339	    /**
340	     * Applies the household rule to an owner being created. An owner belongs to the same household
341	     * as an existing owner when their lastName and address both match (compared case-insensitively
342	     * with runs of whitespace collapsed to a single space).
343	     *
344	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
345	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
346	     * does, the new owner and every existing owner in the household are assigned the same stable
347	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
348	     *
349	     * @param owner            the owner being created
350	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
351	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
352	     *                                     the request did not opt in with {@code sharesHousehold=true}
353	     */
354	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
355	        String lastNameKey = toHouseholdKey(owner.getLastName());
356	        String addressKey = toHouseholdKey(owner.getAddress());
357	        List<Owner> household = this.clinicService.findAllOwners().stream()
358	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
359	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
360	            .toList();
361	        if (household.isEmpty()) {
362	            return;
363	        }
364	        if (!Boolean.TRUE.equals(sharesHousehold)) {
365	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
366	        }
367	        String householdId = householdId(lastNameKey, addressKey);
368	        owner.setHouseholdId(householdId);
369	        for (Owner existing : household) {
370	            if (!householdId.equals(existing.getHouseholdId())) {
371	                existing.setHouseholdId(householdId);
372	                this.clinicService.saveOwner(existing);
373	            }
374	        }
375	    }
376	
377	    /**
378	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
379	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
380	     * lastName and address keys. Being a pure function of the household, every owner in it derives
381	     * the same value regardless of creation order.
382	     *
383	     * @param lastNameKey the normalized household lastName key
384	     * @param addressKey  the normalized household address key
385	     * @return the household identifier
386	     */
387	    private String householdId(String lastNameKey, String addressKey) {
388	        try {
389	            byte[] digest = MessageDigest.getInstance("SHA-256")
390	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
391	            StringBuilder hex = new StringBuilder(digest.length * 2);
392	            for (byte b : digest) {
393	                hex.append(String.format("%02x", b));
394	            }
395	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
396	        } catch (NoSuchAlgorithmException ex) {
397	            throw new IllegalStateException("SHA-256 not available", ex);
398	        }
399	    }
400	
401	    /**
402	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
403	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
404	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
405	     * string.
406	     */
407	    private String toHouseholdKey(String value) {
408	        if (value == null) {
409	            return "";
410	        }
411	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
412	    }
413	
414	    /**
415	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
416	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
417	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
418	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
419	     * value, or one that is blank once trimmed, normalizes to an empty string.
420	     *
421	     * @param address the raw address value as submitted, may be {@code null}
422	     * @return the normalized address, or an empty string when none was supplied
423	     */
424	    private String normalizeAddress(String address) {
425	        if (address == null) {
426	            return "";
427	        }
428	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
429	        if (collapsed.isEmpty()) {
430	            return "";
431	        }
432	        String[] tokens = collapsed.split(" ");
433	        StringBuilder normalized = new StringBuilder(collapsed.length());
434	        for (int i = 0; i < tokens.length; i++) {
435	            if (i > 0) {
436	                normalized.append(' ');
437	            }
438	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
439	        }
440	        return normalized.toString();
441	    }
442	
443	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
444	    @Override
445	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
446	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
447	        if (currentOwner == null) {
448	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
449	        }
450	        currentOwner.setAddress(ownerFieldsDto.getAddress());
451	        currentOwner.setCity(ownerFieldsDto.getCity());
452	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
453	        currentOwner.setLastName(ownerFieldsDto.getLastName());
454	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
455	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
456	        this.clinicService.saveOwner(currentOwner);
457	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
458	    }
459	
460	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
461	    @Transactional
462	    @Override
463	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
464	        Owner owner = this.clinicService.findOwnerById(ownerId);
465	        if (owner == null) {
466	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
467	        }
468	        this.clinicService.deleteOwner(owner);
469	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
470	    }
471	
472	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
473	    @Override
474	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
475	        Owner owner = this.clinicService.findOwnerById(ownerId);
476	        if (owner == null) {
477	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
478	        }
479	        HttpHeaders headers = new HttpHeaders();
480	        Pet pet = petMapper.toPet(petFieldsDto);
481	        owner.setId(ownerId);
482	        pet.setOwner(owner);
483	        pet.getType().setName(null);
484	        this.clinicService.savePet(pet);
485	        PetDto petDto = petMapper.toPetDto(pet);
486	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
487	            .buildAndExpand(pet.getId()).toUri());
488	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
489	    }
490	
491	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
492	    @Override
493	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
494	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
495	        if (currentOwner != null) {
496	            Pet currentPet = this.clinicService.findPetById(petId);
497	            if (currentPet != null) {
498	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
499	                currentPet.setName(petFieldsDto.getName());
500	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
501	                this.clinicService.savePet(currentPet);
502	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
503	            }
504	        }
505	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
506	    }
507	
508	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
509	    @Override
510	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
511	        HttpHeaders headers = new HttpHeaders();
512	        Visit visit = visitMapper.toVisit(visitFieldsDto);
513	        Pet pet = new Pet();
514	        pet.setId(petId);
515	        visit.setPet(pet);
516	        this.clinicService.saveVisit(visit);
517	        VisitDto visitDto = visitMapper.toVisitDto(visit);
518	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
519	            .buildAndExpand(visit.getId()).toUri());
520	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
521	    }
522	
523	
524	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
525	    @Override
526	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
527	        Owner owner = this.clinicService.findOwnerById(ownerId);
528	        if (owner != null) {
529	            Pet pet = owner.getPet(petId);
530	            if (pet != null) {
531	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
532	            }
533	        }
534	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
535	    }
536	}
